const quellen = $('Mattermost-Text bauen').all().map((item) => item.json);
const kanaele = $input.all().map((item) => item.json).filter((kanal) => kanal && kanal.name);
return quellen.map((quelle) => {
  const ziel = kanaele.find((kanal) => kanal.name === quelle.channel);
  if (!ziel) {
    throw new Error('Kanal "' + quelle.channel + '" nicht gefunden oder n8n-bot ist dort kein Mitglied. Bekannt: ' + kanaele.map((kanal) => kanal.name).join(', '));
  }
  return { json: { ...quelle, channel_id: ziel.id } };
});
